export type SinuaCorePattern =
  | "generating"
  | "typing";

/** Core parameters; unset ones keep the pattern's values. */
export interface SinuaCoreParams {
  /** Draw the highlight as one smooth gradient band instead of stepped layers. Patterns: generating. */
  highlightFill?: boolean;
  /** Highlight length as a fraction of the track. Range 0.05...1 (fraction). Patterns: generating. */
  highlightLength?: number;
  /** Ink hue in degrees; applies once saturation is above 0. Range 0...360 (deg). */
  hue?: number;
  /** How present the whole visual is: 1 draws it as the pattern defines it, lower fades everything including its halos. A voice assistant rests below 1 when idle and comes to full ink when it listens. Range 0...1 (fraction). */
  ink?: number;
  /** How far the ink moves from grey toward the hue (0 = the grey ink). Range 0...1 (fraction). */
  saturation?: number;
  /** Track thickness as a fraction of the frame. Range 0.01...0.5 (fraction). Patterns: generating. */
  thickness?: number;
  /** Opacity of the track behind the highlight (0 = highlight only). Range 0...1 (fraction). Patterns: generating. */
  trackOpacity?: number;
  /** Seconds per highlight sweep. Range 0.05...30 (s). */
  period?: number;
  /** Track length as a fraction of the frame. Range 0.1...1 (fraction). Patterns: generating. */
  length?: number;
  /** Bounce height as a fraction of the frame. Range 0...0.5 (fraction). Patterns: typing. */
  bounceAmplitude?: number;
  /** Seconds between one dot's bounce and the next. Range 0...5 (s). Patterns: typing. */
  delay?: number;
  /** Number of bouncing dots. Range 1...6. Patterns: typing. */
  dotCount?: number;
  /** Dot radius as a fraction of the frame. Range 0.01...0.3 (fraction). Patterns: typing. */
  dotSize?: number;
  /** Gap between dots as a fraction of the frame. Range 0.02...0.5 (fraction). Patterns: typing. */
  spacing?: number;
  glow?: SinuaGlow;
  noise?: SinuaNoise;
  pulse?: SinuaPulse;
  gradient?: SinuaGradient;
  color?: SinuaColor;
  liquid?: SinuaLiquid;
  particles?: SinuaParticles;
  holographic?: SinuaHolographic;
}

